                AgentEvent::TextDelta { delta, .. } => {
                    if delta.is_empty() {
                        continue;
                    }
                    bridge_bus.emit(AgentTurnEvent::AssistantTextDelta {
                        session_id: bridge_session_id,
                        turn_id: bridge_turn_id,
                        delta,
                    });
                }
