                    // turn's `bridge_session_id`, so the SSE filter scopes it to
                    // the originating session — a second session never sees it.
                    use ocean_agent_sdk::surface::{
                        ActorRef, CanvasId, PatchId, SurfaceId, SurfacePatchEnvelope,
                    };
